SET NOCOUNT ON;
DECLARE @Hash nvarchar(128)=N'$(MigrationSha256)';
IF LEN(@Hash)<>64 OR @Hash LIKE N'%[^0-9a-fA-F]%' OR NOT EXISTS(SELECT 1 FROM dbo.SchemaMigrationHistory WHERE MigrationId=N'0055_stage2_document_delegation' AND FileSha256=UPPER(@Hash) AND Status=N'Applied') THROW 57511,N'Document authority ledger mismatch.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.CanAccess')))),0x)<>0xE3661AADF166D4E8DDB7F71707F740E17982E64AE5649B5EBAC977EF6014D9E4 THROW 57511,N'Document contract differs: DocumentSecurity.CanAccess.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.SetGrant')))),0x)<>0x522C04B186DE3F0F2004834419B4E6CA3D19FA9CA828270C98EB5D1C15C923DF THROW 57511,N'Document contract differs: DocumentSecurity.SetGrant.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.GrantOptions')))),0x)<>0x570F871037C23464135CB28B803ABFD2259176DC2CFAEBE82359802638E3C55D THROW 57511,N'Document contract differs: DocumentSecurity.GrantOptions.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.ListGrants')))),0x)<>0xCA95D736BE9937E0D9B4AFD1A5CF7D195F94A09FC68459E18F8441528DAAB919 THROW 57511,N'Document contract differs: DocumentSecurity.ListGrants.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.GrantAuditImmutable')))),0x)<>0x3EFE62B4C22299264BA432534C4FC14C81AB408163B57E4FF893A9AF833BE381 THROW 57511,N'Document contract differs: DocumentSecurity.GrantAuditImmutable.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_GetOptions')))),0x)<>0x9B2DFBBC0C65307A6AA1B81508028ADB9683E10331297114F3235094F9C0F7F1 THROW 57511,N'Document contract differs: DocumentSecurity.Document_GetOptions.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_List')))),0x)<>0x1BA1BD78D1D75F09D97976065794819E1316B01EF75B139B46C125B67EB7C8CC THROW 57511,N'Document contract differs: DocumentSecurity.Document_List.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_Summary')))),0x)<>0x4FD50E651734CBB4288D38703D2D8166AFDEDE3FF77897EAD3A3426B2BFE8DBD THROW 57511,N'Document contract differs: DocumentSecurity.Document_Summary.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_GetById')))),0x)<>0xEE0A3DFC0CAB721937F082395193D964CC02C509331E1D0BD7031A7FEEF6E591 THROW 57511,N'Document contract differs: DocumentSecurity.Document_GetById.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_GetForEdit')))),0x)<>0x4D51EC468ACC6A59EBEB08607AA11DE2096F5D71004C78F7EE4BFC84C2D54125 THROW 57511,N'Document contract differs: DocumentSecurity.Document_GetForEdit.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_Create')))),0x)<>0xA5F4DC2BF902985D08E9B2E13BBB8E291DB41CC931AE3A6C5203FCD633918A74 THROW 57511,N'Document contract differs: DocumentSecurity.Document_Create.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_MarkReady')))),0x)<>0xFF09218EC4D5559A1C905BC785ABE408D0A71566CD51BE9DD8C6968915FC3B6D THROW 57511,N'Document contract differs: DocumentSecurity.Document_MarkReady.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_DeletePending')))),0x)<>0x0641F977B28AF96313B3945CFF1D98AD6AF3E48B1AC2AC7FB771A58724B39F5B THROW 57511,N'Document contract differs: DocumentSecurity.Document_DeletePending.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_Update')))),0x)<>0xEA61FC63AF00A2A9A6B5215C1DF440C60AAA4B4871F9C168550E1F7CDA02AFEE THROW 57511,N'Document contract differs: DocumentSecurity.Document_Update.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_ReplaceFile')))),0x)<>0xCEC1BDA0A4C4A8B61AD643B6005DF75D206D89AFD046F41AD3014DE9F5E8CEB6 THROW 57511,N'Document contract differs: DocumentSecurity.Document_ReplaceFile.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_MarkVersionReady')))),0x)<>0x0802F6C0F5E2B13E6465C97CB614E14446D6374EC61DDC11FE81B9C76BE25A0F THROW 57511,N'Document contract differs: DocumentSecurity.Document_MarkVersionReady.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_DeletePendingVersion')))),0x)<>0xD8FCBF70A4BC0D3C25BEEA4608E719C7DFE826CB96BFF9DD2FE00329D5FADF5D THROW 57511,N'Document contract differs: DocumentSecurity.Document_DeletePendingVersion.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_SetStatus')))),0x)<>0xBF9B73C4995F930FF9B37B33D84A5B062F4FBBD0495E23D9C6AADE1299D90D23 THROW 57511,N'Document contract differs: DocumentSecurity.Document_SetStatus.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_GetFileMetadata')))),0x)<>0xAA360F1CEE8CBD01F3B1B657AA11F748232C37DAA18C845F201AD36CFBD36079 THROW 57511,N'Document contract differs: DocumentSecurity.Document_GetFileMetadata.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.DocumentAlert_Generate')))),0x)<>0x4FBCAE5BDD1EE49BA00A8FE96EF4CDBC7BA338741A78BFFB5173060754116BAA THROW 57511,N'Document contract differs: DocumentSecurity.DocumentAlert_Generate.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.DocumentAlert_List')))),0x)<>0x45FC1CF6C90EB95E0AFB1AEC82F383E5A4BFB7342F8C0CB2BD8FE7775A59D6E2 THROW 57511,N'Document contract differs: DocumentSecurity.DocumentAlert_List.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.DocumentAlert_Summary')))),0x)<>0x884078E52DBA57620DD8B1D602AAE20BC041FBB70D45B9E87D990D1B9499C07F THROW 57511,N'Document contract differs: DocumentSecurity.DocumentAlert_Summary.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.DocumentAlert_MarkHandled')))),0x)<>0x2298FC3E0C45EA70E125F5D2FAF2623207FB65AAEE9CEF51CBEA80AFE20FC4B1 THROW 57511,N'Document contract differs: DocumentSecurity.DocumentAlert_MarkHandled.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.DocumentAlert_RegisterNotification')))),0x)<>0xAA46C4E848E8C31370F5518312B833FEB4406C9E694F5B2498185E22B046E85B THROW 57511,N'Document contract differs: DocumentSecurity.DocumentAlert_RegisterNotification.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_AuthorizeDownload')))),0x)<>0x5A81F701EB7B01F566D3BD891B14CFA406670E29C13B4C918FF834365827F749 THROW 57511,N'Document contract differs: DocumentSecurity.Document_AuthorizeDownload.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'DocumentSecurity.Document_PublicationReceipt')))),0x)<>0xE20A5AFCF203E8D3DAB632988730463C4B941BBC841406B7E8FABA5AE399A739 THROW 57511,N'Document contract differs: DocumentSecurity.Document_PublicationReceipt.',1;
IF NOT EXISTS(SELECT 1 FROM sys.triggers WHERE object_id=OBJECT_ID(N'DocumentSecurity.GrantAuditImmutable') AND is_disabled=0) THROW 57511,N'Audit immutability unavailable.',1;
SELECT N'PASS' AS DocumentDelegationVerification;
